CREATE OR REPLACE FUNCTION public.erp_list_cloud_sales_workflow_orders(p_company_id uuid) RETURNS setof jsonb LANGUAGE SQL SECURITY DEFINER SET search_path=public AS  SELECT jsonb_build_object( 'id', o.id::text, 'status', o.status  REVOKE ALL ON FUNCTION public.erp_list_cloud_sales_workflow_orders(uuid) FROM PUBLIC, ANON; GRANT EXECUTE ON FUNCTION public.erp_list_cloud_sales_workflow_orders(uuid) TO authenticated;
